4685			return stale
4686		}
4687		var seedOnly, headOnly int
4688		if _, err := fmt.Sscanf(strings.TrimSpace(counts), "%d %d", &seedOnly, &headOnly); err != nil {
4689			return stale
4690		}
4691		switch {
4692		case seedOnly > 0 && headOnly > 0:
4693			stale.Detail = fmt.Sprintf("repository context and docs were built from %s, which diverged from HEAD (%d and %d commits from their merge base); run %s", seedCommit, seedOnly, headOnly, refresh)
4694			return stale
4695		case headOnly > seedFreshDriftBound || seedOnly > seedFreshDriftBound:
4696			stale.Detail = fmt.Sprintf("repository context and docs were built from %s, %d commits from HEAD; run %s", seedCommit, max(seedOnly, headOnly), refresh)
4697			return stale
4698		case headOnly > 0:
4699			return staleAxis{State: "ok", Detail: fmt.Sprintf("repository context and docs were built from %s, %d commit(s) behind HEAD", seedCommit, headOnly), Current: head, Indexed: seedCommit}
4700		default:
