1872	// materializeHeadSnapshot extracts the committed HEAD tree into a temporary
1873	// directory (`git archive`, extracted in-process — no tar binary needed) so a
1874	// dirty worktree can still seed from committed state (COR-2316). Only regular
1875	// files are written; a committed symlink is skipped, matching the caution the
1876	// on-disk scan applies through its symlink rejection. The caller owns cleanup.
1877	func materializeHeadSnapshot(ctx context.Context, runner CommandRunner, repoDir string) (dir, commit string, cleanup func(), err error) {
1878		commit, err = clibase.GitScalar(ctx, runner, repoDir, "rev-parse", "HEAD")
1879		if err != nil {
1880			return "", "", nil, fmt.Errorf("resolve HEAD for committed snapshot: %w", err)
1881		}
1882		archive, _, err := runner.Run(ctx, repoDir, "git", "archive", "--format=tar", commit)
1883		if err != nil {
1884			return "", "", nil, fmt.Errorf("archive committed tree %s: %w", commit, err)
1885		}
1886		dir, err = os.MkdirTemp("", "entire-brain-seed-head-")
1887		if err != nil {
1888			return "", "", nil, fmt.Errorf("create snapshot directory: %w", err)
1889		}
1890		cleanup = func() { _ = os.RemoveAll(dir) }
1891		reader := tar.NewReader(bytes.NewReader(archive))
1892		for {
1893			header, nextErr := reader.Next()
1894			if errors.Is(nextErr, io.EOF) {
1895				break
1896			}
1897			if nextErr != nil {
1898				cleanup()
1899				return "", "", nil, fmt.Errorf("read committed tree archive: %w", nextErr)
1900			}
1901			rel := filepath.FromSlash(header.Name)
1902			// git emits safe names; the check is a belt against a hostile archive.
1903			if !filepath.IsLocal(rel) {
1904				continue
1905			}
1906			target := filepath.Join(dir, rel)
1907			switch header.Typeflag {
1908			case tar.TypeDir:
1909				if mkErr := os.MkdirAll(target, 0o755); mkErr != nil {
1910					cleanup()
1911					return "", "", nil, fmt.Errorf("extract committed tree: %w", mkErr)
1912				}
1913			case tar.TypeReg:
1914				if mkErr := os.MkdirAll(filepath.Dir(target), 0o755); mkErr != nil {
1915					cleanup()
1916					return "", "", nil, fmt.Errorf("extract committed tree: %w", mkErr)
1917				}
1918				f, openErr := os.OpenFile(target, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o600)
1919				if openErr != nil {
1920					cleanup()
1921					return "", "", nil, fmt.Errorf("extract committed tree: %w", openErr)
1922				}
1923				_, copyErr := io.Copy(f, reader)
1924				closeErr := f.Close()
1925				if copyErr != nil || closeErr != nil {
1926					cleanup()
1927					return "", "", nil, fmt.Errorf("extract committed tree %s: copy=%v close=%v", rel, copyErr, closeErr)
1928				}
1929			default:
1930				// Symlinks, hardlinks, devices: not content the seed reads.
1931			}
1932		}
1933		return dir, commit, cleanup, nil
1934	}
