			warning := strings.TrimSpace(stderr.String())
			if warning == "" {
				warning = strings.TrimSpace(stdout.String())
			}
			if warning != "" {
				phaseManifest.Warnings = append(phaseManifest.Warnings, truncateAgentWarning(warning))
			}
